(function(){
  var jsPDFAPI = window.jspdf && window.jspdf.jsPDF && window.jspdf.jsPDF.API;
  if (!jsPDFAPI) return;
  var BRICOLAGE = '';
  var INSTRUMENT = '';
  var INSTRUMENT_SEMI = '';
  jsPDFAPI.events.push(['addFonts', function(){
    this.addFileToVFS('Bricolage-ExtraBold.ttf', BRICOLAGE);
    this.addFont('Bricolage-ExtraBold.ttf', 'Bricolage', 'bold');
    this.addFileToVFS('Instrument-Regular.ttf', INSTRUMENT);
    this.addFont('Instrument-Regular.ttf', 'Instrument', 'normal');
    this.addFileToVFS('Instrument-SemiBold.ttf', INSTRUMENT_SEMI);
    this.addFont('Instrument-SemiBold.ttf', 'Instrument', 'bold');
  }]);
})();
